import itertools

def compute_C(seq):
    n = len(seq)
    C = {}
    for k in range(1, n):
        s = 0
        for i in range(n - k):
            s += seq[i] * seq[i+k]
        C[k] = s
    return C

def sum_sq_C(seq):
    C = compute_C(seq)
    return sum(v*v for v in C.values())

# Search
n = 11
solutions = []
for bits in itertools.product([-1, 1], repeat=n):
    # constraints: seq[1]=1, seq[8]=1 (0-indexed)
    if bits[1] != 1: continue
    if bits[8] != 1: continue
    C = compute_C(bits)
    if C[6] != 0: continue
    if C[9] != 1: continue
    ss = sum(v*v for v in C.values())
    if ss <= 23:
        solutions.append((bits, ss, C))

print(f"Number of solutions: {len(solutions)}")
for seq, ss, C in solutions:
    print(f"seq={list(seq)}, sum_sq={ss}, C={C}")
